CREATE TABLE anon.metrics_store ( `entity_key` String, `event_date` Date, `event_timestamp` DateTime64(3,'UTC'), `entity_group` LowCardinality(String), `metric_value` UInt64, `metric_ratio` Decimal(18,6), `tag_values` Array(String), `attr_map` Map(String,String) ) ENGINE=MergeTree PARTITION BY toYYYYMM(event_date) ORDER BY(entity_group,entity_key,event_timestamp) TTL event_date + toIntervalDay(30) SETTINGS index_granularity=8192